  border-radius: 7px;
  background: #202a32;
  color: var(--ink);
  text-align: center;
  display: grid;
  place-items: center;
  overflow: hidden;
}

.asset-card.active {
  border-color: var(--accent);
  background: #2c352f;
}

.asset-card img {
  width: 100%;
  height: 100%;
  max-width: 42px;
  max-height: 42px;
  object-fit: contain;
  object-position: center;
  image-rendering: pixelated;
  display: block;
  border-radius: 4px;
  background: #2a343b;
}

.asset-card span {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
}

.asset-card small {
  display: none;
}

.asset-card.asset-note {
  aspect-ratio: auto;
  width: 118px;
  min-height: 68px;
  padding: 10px;
  place-items: start;
  text-align: left;
}

